// SWEEP #10 · T11 · block A — THE KITCHEN ROUTE, CALLED IN MEMORY (STUB). P180041–P180240.
//
// The real app/api/kitchen/[...path]/route.ts, bundled with esbuild, called with real NextRequests
// against the shared stub database. Every branch executes; no socket opens. This is where the states
// the happy path never visits are DRIVEN: a missing login, a database blip, a blocked device, a second
// restaurant's ids, a cancelled ticket, a served one, a module off, the queue stopped.
import { check, world, call, G, unscoped, RID, RID2, F } from "./lib.mjs";

const R = F.route;
const T = () => new Date(Date.now() - 5 * 60000).toISOString();
const ord = (id, extra = {}) => ({ id, restaurant_id: RID, status: "preparing", archived: false, deleted_at: null, table_number: 4, kot_no: 11, created_at: T(), items: [{ title: "Soup", qty: 1, status: "preparing" }], session_id: null, ...extra });
const item = (id, order_id, extra = {}) => ({ id, order_id, restaurant_id: RID, status: "preparing", title: "Soup", qty: 1, created_at: T(), ...extra });
const BASE = () => ({
  orders: [ord("o1"), ord("o2", { status: "received", table_number: 5, kot_no: 12 }), ord("x1", { restaurant_id: RID2, table_number: 4, kot_no: 99 })],
  order_items: [item("i1", "o1"), item("i2", "o1", { title: "Bread" }), item("i3", "o2", { status: "received" }), item("xi", "x1", { restaurant_id: RID2 })],
  menu_items: [{ id: "d1", restaurant_id: RID, title: "Soup", category: "Starters", tags: [] }, { id: "d2", restaurant_id: RID, title: "Cake", category: "Dessert", tags: ["sold-out", "veg"] }, { id: "dx", restaurant_id: RID2, title: "Theirs", tags: [] }],
  aggregator_orders: [{ id: "p1", restaurant_id: RID, source: "zomato", status: "accepted", kot_no: 40, created_at: T(), items: [{ title: "Wrap", qty: 2 }] },
    { id: "p2", restaurant_id: RID, source: "parcel", status: "new", kot_no: 41, created_at: T(), items: [] },
    { id: "px", restaurant_id: RID2, source: "zomato", status: "accepted", kot_no: 77, created_at: T(), items: [] }],
});
const w = (o = {}) => world({ ...o, fix: { ...BASE(), ...(o.fix || {}) } });
const st = (r) => r.status;
const said = (r, re) => re.test(String(r.json && r.json.error));

// ── A1 · who may knock — P180041–P180056 ───────────────────────────────────────────────────────
check("P180041", R, "no login → 401 with the sentence that sends the panel to /login", "STUB — the real route, in memory", async () => { await w({ who: "nobody" }); const r = await call("GET", "board"); return { ok: st(r) === 401 && said(r, /please log in/), note: `${st(r)}` }; });
check("P180042", R, "a database blip during the login lookup → 503, so the panel stays signed in and retries", "STUB", async () => { await w({ who: "blip" }); const r = await call("GET", "board"); return { ok: st(r) === 503 && said(r, /retrying/), note: `${st(r)}` }; });
check("P180043", R, "the kitchen login is let in to the board", "STUB", async () => { await w(); return st(await call("GET", "board")) === 200; });
check("P180044", R, "a MANAGER login is refused (item 2) — 403, plain sentence", "STUB", async () => { await w({ who: "manager" }); const r = await call("GET", "board"); return { ok: st(r) === 403 && said(r, /kitchen login/), note: `${st(r)}` }; });
check("P180045", R, "an OWNER login is refused (item 2)", "STUB", async () => { await w({ who: "owner" }); return st(await call("GET", "board")) === 403; });
check("P180046", R, "a manager is refused on every WRITE too — no 86 through the side door", "STUB", async () => { await w({ who: "manager" }); const r = await call("POST", "dishes/d1/sold-out", { body: { value: true } }); const g = await G(); return { ok: st(r) === 403 && !g.WRITES.length, note: `${st(r)} · ${g.WRITES.length} writes` }; });
check("P180047", R, "an owner is refused on a write before anything is touched", "STUB", async () => { await w({ who: "owner" }); const r = await call("POST", "orders/o1/ready"); const g = await G(); return st(r) === 403 && !g.WRITES.length; });
check("P180048", R, "the admin super-user (view-as) is let in with ?rid", "STUB", async () => { await w({ who: "admin" }); return st(await call("GET", "board", { query: `?rid=${RID}` })) === 200; });
check("P180049", R, "the admin with NO restaurant pinned is told to open it from the console (R48 wording kept)", "STUB", async () => { await w({ who: "admin" }); const r = await call("GET", "board"); return { ok: st(r) === 400 && said(r, /No restaurant scope/), note: `${st(r)}` }; });
check("P180050", R, "the admin's ?rid decides the restaurant — French House's board names French House", "STUB", async () => { await w({ who: "admin" }); const r = await call("GET", "board", { query: `?rid=${RID}` }); return r.json.restaurant && r.json.restaurant.id === RID; });
check("P180051", R, "the admin viewing Aangan gets Aangan's tickets only", "STUB", async () => { await w({ who: "admin" }); const r = await call("GET", "board", { query: `?rid=${RID2}` }); const ids = r.json.orders.map((o) => o.id); return { ok: ids.length === 1 && ids[0] === "x1", note: ids.join(",") }; });
check("P180052", R, "a staff login's restaurant comes from its session — a ?rid on the URL is ignored", "STUB", async () => { await w(); const r = await call("GET", "board", { query: `?rid=${RID2}` }); const ids = r.json.orders.map((o) => o.id); return { ok: !ids.includes("x1") && ids.includes("o1"), note: ids.join(",") }; });
check("P180053", R, "a write with a staff login and a ?rid for another restaurant still acts on the login's own", "STUB", async () => { await w(); const r = await call("POST", "orders/x1/ready", { query: `?rid=${RID2}` }); const g = await G(); return { ok: st(r) === 404 && !g.WRITES.some((x) => x.table === "orders"), note: `${st(r)}` }; });
check("P180054", R, "a blocked device's board read goes dark: 403 with the CODE device_blocked", "STUB — a device id of its own (the route memoises a block answer for 30s per device, by design)", async () => { await w({ blocked: [`${RID}:dev-blocked-1`] }); const r = await call("GET", "board", { headers: { "x-lfh-device": "dev-blocked-1" } }); return { ok: st(r) === 403 && r.json.reason === "device_blocked" && r.json.blocked === true, note: JSON.stringify(r.json).slice(0, 80) }; });
check("P180055", R, "a device blocked at ANOTHER restaurant is not blocked here", "STUB — a device id of its own", async () => { await w({ blocked: [`${RID2}:dev-blocked-2`] }); return st(await call("GET", "board", { headers: { "x-lfh-device": "dev-blocked-2" } })) === 200; });
check("P180056", R, "a blocked device's WRITE is refused 403 and writes nothing", "STUB", async () => { await w({ blocked: [`${RID}:dev-test`] }); const r = await call("POST", "orders/o1/ready"); const g = await G(); return st(r) === 403 && !g.WRITES.some((x) => x.table === "orders"); });

// ── A2 · the full board — P180057–P180090 ──────────────────────────────────────────────────────
const board = async (o = {}, q = "?autojobs=1") => { await w(o); return call("GET", "board", { query: q }); };
check("P180057", R, "the board answers every key the panel reads", "STUB", async () => { const r = await board(); const need = ["orders", "items", "dishes", "platform", "platformAccept", "autoPrintKot", "kotPrintTarget", "helper", "printTarget", "printRefused", "tableNames", "tableTags", "restaurant", "printJobs", "queuedFor", "station", "waiting", "stuckAfterMs"]; const miss = need.filter((k) => !(k in r.json)); return { ok: !miss.length, note: miss.join(",") || `${need.length} keys` }; });
check("P180058", R, "only THIS restaurant's tickets are on it", "STUB", async () => { const r = await board(); return r.json.orders.every((o) => o.restaurant_id === RID); });
check("P180059", R, "only this restaurant's dish rows ride along", "STUB", async () => { const r = await board(); return r.json.items.every((i) => i.restaurant_id === RID) && r.json.items.length === 3; });
check("P180060", R, "the 86 board's dish list is this restaurant's menu only", "STUB", async () => { const r = await board(); const ids = r.json.dishes.map((d) => d.id); return { ok: ids.includes("d1") && ids.includes("d2") && !ids.includes("dx"), note: ids.join(",") }; });
check("P180061", R, "no other restaurant's delivery ticket is on it", "STUB", async () => { const r = await board({ settings: { platform_channels: { zomato: { on: true } } } }); return !r.json.platform.some((p) => p.id === "px"); });
check("P180062", R, "every board statement names the restaurant (no unscoped read)", "STUB — every statement in the query log", async () => { await board(); const u = await unscoped(); return { ok: !u.length, note: u.map((q) => q.table).join(",") || "all scoped" }; });
check("P180063", R, "the restaurant read is a by-id lookup of the session's restaurant", "STUB", async () => { await board(); const g = await G(); const q = g.SCOPE_LOG.find((x) => x.table === "restaurants"); return !!q && q.filters.some((f) => f.col === "id" && f.val === RID); });
check("P180064", R, "who punched an order (placed_by / placed_by_id) never leaves the server", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { placed_by: "Ravi", placed_by_id: "w9" })] } }); const o = r.json.orders[0]; return { ok: o && !("placed_by" in o) && !("placed_by_id" in o), note: Object.keys(o || {}).join(",") }; });
check("P180065", R, "a waiter-punched order carries no guest flag", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { placed_by: "Ravi", placed_by_id: "w9" })] } }); return !("guest" in r.json.orders[0]) || r.json.orders[0].guest !== 1; });
check("P180066", R, "a guest's own order carries guest: 1 so it can ring", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { placed_by: null, placed_by_id: null })] } }); return r.json.orders[0].guest === 1; });
check("P180067", R, "a cancelled order is not handed to the board", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { status: "cancelled" })] } }); return !r.json.orders.some((o) => o.id === "o1"); });
check("P180068", R, "a served order is not handed to the board (activeOnly)", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { status: "served" })] } }); return !r.json.orders.some((o) => o.id === "o1"); });
check("P180069", R, "a binned (soft-deleted) order never reaches the board", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { deleted_at: T() })] } }); return !r.json.orders.some((o) => o.id === "o1"); });
check("P180070", R, "an archived order never reaches the board", "STUB", async () => { const r = await board({ fix: { orders: [ord("o1", { archived: true })] } }); return !r.json.orders.some((o) => o.id === "o1"); });
check("P180071", R, "a zomato ticket shows only while the platform channel is ON", "STUB", async () => { const on = await board({ settings: { platform_channels: { zomato: { on: true } } } }); const off = await board({ settings: { platform_channels: { zomato: { on: false } } } }); return { ok: on.json.platform.some((p) => p.id === "p1") && !off.json.platform.some((p) => p.id === "p1"), note: `on ${on.json.platform.length} · off ${off.json.platform.length}` }; });
check("P180072", R, "a counter PARCEL ticket shows whatever the delivery channels say (parcel module is always on)", "STUB", async () => { const r = await board(); return r.json.platform.some((p) => p.id === "p2"); });
check("P180073", R, "a website order arrives under source 'takeaway' only when the website channel is on", "STUB", async () => {
  const fix = { aggregator_orders: [{ id: "pw", restaurant_id: RID, source: "takeaway", status: "accepted", kot_no: 5, created_at: T(), items: [] }] };
  const on = await board({ fix, settings: { platform_channels: { website: { on: true } } } }); const off = await board({ fix });
  return on.json.platform.length === 1 && off.json.platform.length === 0;
});
check("P180074", R, "a swiggy ticket needs the swiggy channel, not zomato's", "STUB", async () => {
  const fix = { aggregator_orders: [{ id: "ps", restaurant_id: RID, source: "swiggy", status: "accepted", kot_no: 5, created_at: T(), items: [] }] };
  const z = await board({ fix, settings: { platform_channels: { zomato: { on: true } } } }); const s = await board({ fix, settings: { platform_channels: { swiggy: { on: true } } } });
  return z.json.platform.length === 0 && s.json.platform.length === 1;
});
check("P180075", R, "a channel stored as on: 'yes' (not exactly true) does not switch it on", "STUB", async () => { const r = await board({ settings: { platform_channels: { zomato: { on: "yes" } } } }); return !r.json.platform.some((p) => p.id === "p1"); });
check("P180076", R, "a handed-over or cancelled delivery is never on the board", "STUB", async () => {
  const fix = { aggregator_orders: [{ id: "h1", restaurant_id: RID, source: "parcel", status: "handed_over", created_at: T(), items: [] }, { id: "h2", restaurant_id: RID, source: "parcel", status: "cancelled", created_at: T(), items: [] }] };
  const r = await board({ fix }); return r.json.platform.length === 0;
});
check("P180077", R, "platformAccept mirrors the manager's 'kitchen can accept' switch", "STUB", async () => { const a = await board({ settings: { kitchen_can_accept_platform: true } }); const b = await board(); return a.json.platformAccept === true && b.json.platformAccept === false; });
check("P180078", R, "auto-print is ON for this screen only when the admin allowed it AND it is switched on", "STUB", async () => {
  const both = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true } });
  const onlyOn = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: false } });
  const onlyAllowed = await board({ settings: { auto_print_kot: false, auto_print_kot_allowed: true } });
  return { ok: both.json.autoPrintKot === true && !onlyOn.json.autoPrintKot && !onlyAllowed.json.autoPrintKot, note: `${both.json.autoPrintKot}/${onlyOn.json.autoPrintKot}/${onlyAllowed.json.autoPrintKot}` };
});
check("P180079", R, "with no printing route at all, the kitchen screen is the default printer (mig 372, no toggle)", "STUB", async () => { const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true } }); return r.json.printTarget.kind === "screen" && r.json.printTarget.panel === "kitchen" && r.json.printRefused === null; });
check("P180080", R, "slips routed to the MANAGER screen: this screen is not the printer and says 'counter'", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true, modules: { printing: { routes: { kot: { via: "screen", panel: "manager" } } } } } });
  return { ok: r.json.autoPrintKot === false && r.json.kotPrintTarget === "counter" && r.json.printRefused === "other_panel", note: `${r.json.autoPrintKot} ${r.json.kotPrintTarget} ${r.json.printRefused}` };
});
check("P180081", R, "slips switched to Nobody: this screen prints nothing and is told 'off'", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true, modules: { printing: { routes: { kot: { via: "off" } } } } } });
  return { ok: r.json.autoPrintKot === false && r.json.printRefused === "off", note: `${r.json.printRefused}` };
});
check("P180082", R, "slips owned by a live COMPUTER: helper is named, this screen does not print", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true, modules: { printing: { routes: { kot: { agent: "a1", printer: "POS_80" } } } } }, fix: { print_agents: [{ id: "a1", restaurant_id: RID, name: "Shop PC", revoked_at: null, last_seen_at: new Date().toISOString(), created_at: T(), printers: [] }] } });
  return { ok: r.json.helper.owned === true && r.json.helper.printer === "POS_80" && r.json.autoPrintKot === false && r.json.printRefused === "computer", note: JSON.stringify(r.json.helper).slice(0, 90) };
});
check("P180083", R, "a route naming a computer that was REMOVED gives the slips back to the kitchen screen", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true, modules: { printing: { routes: { kot: { agent: "gone", printer: "POS_80" } } } } } });
  return r.json.helper.owned === false && r.json.autoPrintKot === true;
});
check("P180084", R, "the queue STOPPED: no printer, no jobs, and the reason 'paused' (item 4)", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true, modules: { printing: { paused: true } } }, fix: { print_jobs: [{ id: "j1", restaurant_id: RID, kind: "kot", status: "queued", order_id: "o1", reprint: true, attempts: 0, created_at: T() }] } });
  return { ok: r.json.autoPrintKot === false && r.json.printRefused === "paused" && r.json.printJobs.length === 0 && r.json.queuedFor.length === 0, note: `${r.json.printRefused} · ${r.json.printJobs.length} jobs` };
});
check("P180085", R, "a manager's 'reprint in kitchen' job IS handed to a working kitchen screen", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true }, fix: { print_jobs: [{ id: "j1", restaurant_id: RID, kind: "kot", status: "queued", order_id: "o1", reprint: true, attempts: 0, created_at: T() }] } });
  return { ok: r.json.printJobs.length === 1, note: `${r.json.printJobs.length}` };
});
check("P180086", R, "an AUTO row is handed over only to a panel that asked (?autojobs=1) — an old panel cannot double-print", "STUB", async () => {
  const fix = { print_jobs: [{ id: "ja", restaurant_id: RID, kind: "kot", status: "queued", order_id: "o1", reprint: false, auto: true, attempts: 0, created_at: T() }] };
  const s = { auto_print_kot: true, auto_print_kot_allowed: true };
  const asked = await board({ settings: s, fix }); const old = await board({ settings: s, fix }, "");
  return { ok: asked.json.printJobs.length >= old.json.printJobs.length, note: `asked ${asked.json.printJobs.length} · old panel ${old.json.printJobs.length}` };
});
check("P180087", R, "another restaurant's print job is never handed to this screen", "STUB", async () => {
  const r = await board({ settings: { auto_print_kot: true, auto_print_kot_allowed: true }, fix: { print_jobs: [{ id: "jx", restaurant_id: RID2, kind: "kot", status: "queued", order_id: "x1", reprint: true, attempts: 0, created_at: T() }] } });
  return r.json.printJobs.length === 0;
});
check("P180088", R, "table names ride along exactly as the restaurant set them", "STUB", async () => { const r = await board({ settings: { table_names: { 4: "Patio", 5: "A1" } } }); return r.json.tableNames["4"] === "Patio" && r.json.tableNames["5"] === "A1"; });
check("P180089", R, "a restaurant with no table names gets {} — never null", "STUB", async () => { const r = await board({ settings: { table_names: null } }); return r.json.tableNames && typeof r.json.tableNames === "object"; });
check("P180090", R, "the board still answers when the settings row is missing altogether", "STUB", async () => { await world({ fix: BASE() }); const g = await G(); g.FIX.settings = []; const r = await call("GET", "board"); return { ok: st(r) === 200 && r.json.autoPrintKot === false && r.json.platformAccept === false, note: `${st(r)}` }; });

// ── A3 · marks, station, waiting — P180091–P180104 ─────────────────────────────────────────────
const tagsOn = { table_tags_allowed: true, table_tags_owner_control: false };
check("P180091", R, "VIP / family marks are shipped when the table-types module is ON", "STUB", async () => { const r = await board({ settings: tagsOn, fix: { table_tags: [{ restaurant_id: RID, table_number: 4, tag: "vip" }] } }); return r.json.tableTags["4"] === "vip"; });
check("P180092", R, "…and NOT shipped when the module is off (a mark nobody can clear must not show)", "STUB", async () => { const r = await board({ fix: { table_tags: [{ restaurant_id: RID, table_number: 4, tag: "vip" }] } }); return !Object.keys(r.json.tableTags).length; });
check("P180093", R, "owner-controlled and switched off → no marks", "STUB", async () => { const r = await board({ settings: { table_tags_allowed: true, table_tags_owner_control: true, table_tags_enabled: false }, fix: { table_tags: [{ restaurant_id: RID, table_number: 4, tag: "vip" }] } }); return !Object.keys(r.json.tableTags).length; });
check("P180094", R, "another restaurant's marks never ride on this board", "STUB", async () => { const r = await board({ settings: tagsOn, fix: { table_tags: [{ restaurant_id: RID2, table_number: 4, tag: "vip" }] } }); return !Object.keys(r.json.tableTags).length; });
check("P180095", R, "a mark with a blank tag or blank table is dropped, not shipped as ''", "STUB", async () => { const r = await board({ settings: tagsOn, fix: { table_tags: [{ restaurant_id: RID, table_number: 4, tag: "" }, { restaurant_id: RID, table_number: "", tag: "vip" }] } }); return !Object.keys(r.json.tableTags).length; });
check("P180096", R, "a FAILED marks read still delivers the board (a badge is decoration)", "STUB", async () => { const r = await board({ settings: tagsOn, fail: { table_tags: "throw" } }); return st(r) === 200 && Array.isArray(r.json.orders); });
check("P180097", R, "with nobody printing, the station answer is 'no screen yet'", "STUB", async () => { const r = await board(); return r.json.station && r.json.station.active === null && r.json.station.mine === false; });
check("P180098", R, "this screen holding the station is told 'mine'", "STUB", async () => { const r = await board({ fix: { print_stations: [{ restaurant_id: RID, device_id: "dev-test", active: true, label: "Kitchen screen", panel: "kitchen", last_seen_at: new Date().toISOString() }] } }); return r.json.station.mine === true; });
check("P180099", R, "another restaurant's station is never reported here", "STUB", async () => { const r = await board({ fix: { print_stations: [{ restaurant_id: RID2, device_id: "dev-test", active: true, label: "Theirs", panel: "kitchen", last_seen_at: new Date().toISOString() }] } }); return r.json.station.active === null; });
check("P180100", R, "'tickets waiting' counts this restaurant's queued slips", "STUB", async () => { const r = await board({ fix: { print_jobs: [{ id: "j1", restaurant_id: RID, kind: "kot", status: "queued", order_id: "o1", created_at: T() }, { id: "j2", restaurant_id: RID2, kind: "kot", status: "queued", created_at: T() }] } }); return { ok: r.json.waiting.n === 1, note: JSON.stringify(r.json.waiting) }; });
check("P180101", R, "'how long is stuck' travels with the board (one copy of the threshold)", "STUB", async () => { const r = await board(); return typeof r.json.stuckAfterMs === "number" && r.json.stuckAfterMs > 0; });
check("P180102", R, "the restaurant identity carries name/logo/accent for the header, nothing more", "STUB", async () => { const r = await board(); const k = Object.keys(r.json.restaurant || {}); return k.includes("name") && k.includes("logo_text"); });
check("P180103", R, "the board never carries a settings column it does not need (no tax, no money)", "STUB", async () => { const r = await board({ settings: { tax_rate: 0.05 } }); return !/tax_rate|service_charge|upi_id/.test(r.text); });
check("P180104", R, "the board's menu read is capped (a list that can grow)", "SRC", () => /from\("menu_items"\)\.select\("id,title,category,tags"\)\.eq\("restaurant_id", rid\)\.order\("category"\)\.limit\(2000\)/.test(require_code()));

// ── A4 · the one-table slice — P180105–P180116 ─────────────────────────────────────────────────
check("P180105", R, "?table=4 returns only table 4's tickets", "STUB", async () => { const r = await board({}, "?table=4"); return r.json.orders.every((o) => String(o.table_number) === "4") && r.json.orders.length === 1; });
